def format_call_name(node: ast.AST) -> Optional[str]:
    if isinstance(node, ast.Name):
        return node.id
    elif isinstance(node, ast.Attribute):
        parent = format_call_name(node.value)
        return f"{parent}.{node.attr}" if parent else node.attr
    return None

